#!/usr/bin/env python3
"""Whole-file project instruction ownership shared by team host adapters."""

from __future__ import annotations

import hashlib
import json
import os
import re
import tempfile
from pathlib import Path
from typing import Callable


TEAM_RE = re.compile(r"^[a-z0-9]+(?:-[a-z0-9]+)*$")
CANONICAL_WORKSPACE = "workspace"
HEADER_RE = re.compile(
    r"^<!-- generated by agent-marketplace "
    r"([a-z0-9]+(?:-[a-z0-9]+)*) for (codex|claude|shared); "
    r"do not edit by hand -->$"
)
CHOICE_OPTIONS = ["preserve", "discard", "abort"]


class ProjectInstructionError(ValueError):
    pass


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def validate_workspace(workspace: str) -> str:
    if workspace != CANONICAL_WORKSPACE:
        raise ProjectInstructionError(
            f"workspace {workspace!r} is not supported; use {CANONICAL_WORKSPACE!r}"
        )
    return workspace


def plugin_name(plugin_root: Path) -> str:
    for manifest in (
        plugin_root / ".codex-plugin" / "plugin.json",
        plugin_root / ".claude-plugin" / "plugin.json",
    ):
        try:
            value = str(json.loads(
                manifest.read_text(encoding="utf-8")
            ).get("name", ""))
        except Exception:
            continue
        if TEAM_RE.fullmatch(value):
            return value
    raise ProjectInstructionError("plugin manifest has no valid team name")


def generated_header(team: str, owner: str) -> str:
    return (
        f"<!-- generated by agent-marketplace {team} for {owner}; "
        "do not edit by hand -->"
    )


def read_regular(path: Path) -> str:
    if path.is_symlink():
        raise ProjectInstructionError(f"managed project target is a symbolic link: {path}")
    try:
        return path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return ""
    except (OSError, UnicodeDecodeError) as exc:
        raise ProjectInstructionError(f"managed project target is unreadable: {path}") from exc


def rendered_template(plugin_root: Path, host: str, workspace: str) -> str:
    validate_workspace(workspace)
    filename = "AGENTS.md" if host == "codex" else "CLAUDE.md"
    path = plugin_root / "templates" / filename
    text = read_regular(path)
    if not text:
        raise ProjectInstructionError(f"missing generated project template: {path}")
    team = plugin_name(plugin_root)
    expected = generated_header(team, host)
    if text.splitlines()[0] != expected:
        raise ProjectInstructionError(f"project template has invalid owner header: {path}")
    return text.replace("{{workspace}}", workspace).rstrip() + "\n"


def user_seed(host: str) -> str:
    filename = "AGENTS.user.md" if host == "codex" else "CLAUDE.user.md"
    return (
        "# Project Instructions\n\n"
        f"<!-- {filename} is user-owned. Agent Marketplace seeds it once and "
        "never rewrites it. -->\n"
    )


def append_preserved(current: str, source: str, surface: str) -> str:
    prefix = current
    if prefix and not prefix.endswith("\n"):
        prefix += "\n"
    if prefix and not prefix.endswith("\n\n"):
        prefix += "\n"
    return (
        prefix
        + f"<!-- preserved from {surface} by Agent Marketplace -->\n"
        + source
        + ("" if source.endswith("\n") else "\n")
    )


def choice_request(
    request_id: str,
    surface: str,
    reason: str,
    source: str,
    companion_before: str,
    companion_after: str,
) -> dict:
    return {
        "id": request_id,
        "surface": surface,
        "reason": reason,
        "preview": {
            "source_sha256": sha256_text(source),
            "source_content": source,
            "companion_before_sha256": sha256_text(companion_before),
            "companion_after_sha256": sha256_text(companion_after),
            "companion_after": companion_after,
        },
        "options": CHOICE_OPTIONS,
    }


def resolve_reconciliation(
    *,
    request_id: str,
    surface: str,
    reason: str,
    source: str,
    companion: Path,
    choices: dict[str, str],
    changes: dict[Path, str | None],
    requests: list[dict],
    host: str,
    empty_companion_seed: str = "",
) -> None:
    pending = changes.get(companion)
    current = pending if isinstance(pending, str) else read_regular(companion)
    seed = current or empty_companion_seed or user_seed(host)
    candidate = append_preserved(seed, source, surface)
    selected = choices.get(request_id, "")
    if not selected:
        requests.append(choice_request(
            request_id, surface, reason, source, current, candidate
        ))
        return
    if selected not in CHOICE_OPTIONS:
        raise ProjectInstructionError(
            f"unknown choice {selected!r} for {request_id}"
        )
    if selected == "abort":
        raise ProjectInstructionError(f"owner aborted reconciliation for {surface}")
    if selected == "preserve":
        changes[companion] = candidate


def plan_project_files(
    project_root: Path,
    plugin_root: Path,
    host: str,
    workspace: str,
    *,
    choices: dict[str, str] | None = None,
    seed_user_files: bool = False,
) -> dict:
    if host not in {"codex", "claude"}:
        raise ProjectInstructionError(f"unsupported project instruction host: {host}")
    validate_workspace(workspace)
    choices = choices or {}
    team = plugin_name(plugin_root)
    root_name = "AGENTS.md" if host == "codex" else "CLAUDE.md"
    companion_name = "AGENTS.user.md" if host == "codex" else "CLAUDE.user.md"
    root_path = project_root / root_name
    companion = project_root / companion_name
    existing = read_regular(root_path)
    target = rendered_template(plugin_root, host, workspace)
    changes: dict[Path, str | None] = {}
    requests: list[dict] = []
    root_key = root_name
    host_is_new = not existing

    header = existing.splitlines()[0] if existing else ""
    header_match = HEADER_RE.fullmatch(header)
    reconciliation_source = ""
    reconciliation_reason = ""
    if header_match:
        if header_match.groups() != (team, host):
            raise ProjectInstructionError(
                f"{root_name} belongs to {header_match.group(1)}/{header_match.group(2)}"
            )
    elif existing.strip():
        reconciliation_source = existing
        reconciliation_reason = "unmanaged_content"

    if reconciliation_source:
        resolve_reconciliation(
            request_id=f"{host}.root.{root_name.removesuffix('.md').lower()}",
            surface=root_name,
            reason=reconciliation_reason,
            source=reconciliation_source,
            companion=companion,
            choices=choices,
            changes=changes,
            requests=requests,
            host=host,
        )
    if existing != target:
        changes[root_path] = target
    if (seed_user_files or host_is_new) \
            and not companion.exists() and companion not in changes:
        changes[companion] = user_seed(host)

    override = project_root / "AGENTS.override.md"
    override_state = "absent"
    if host == "codex" and (override.exists() or override.is_symlink()):
        override_text = read_regular(override)
        override_state = "present:" + sha256_text(override_text)
        resolve_reconciliation(
            request_id="codex.root.agents-override",
            surface="AGENTS.override.md",
            reason="reserved_override",
            source=override_text,
            companion=companion,
            choices=choices,
            changes=changes,
            requests=requests,
            host=host,
        )
        if choices.get("codex.root.agents-override") in {"preserve", "discard"}:
            changes[override] = None

    memory_root = project_root / workspace / "memory"
    memory_target = memory_root / "agent-marketplace.md"
    memory_source = read_regular(
        plugin_root / "templates" / "memory" / "agent-marketplace.md"
    )
    if not memory_source:
        raise ProjectInstructionError("missing shared agent-marketplace memory template")
    memory_rendered = (
        generated_header("software-engineering-team", "shared")
        + "\n\n" + memory_source.strip() + "\n"
    )
    memory_existing = read_regular(memory_target)
    memory_key = f"shared:{workspace}/memory/agent-marketplace.md"
    memory_header = memory_existing.splitlines()[0] if memory_existing else ""
    memory_owned = memory_header == generated_header(
        "software-engineering-team", "shared"
    )
    if memory_existing.strip() and not memory_owned:
        memory_user_seed = read_regular(
            plugin_root / "templates" / "memory" / "me.md"
        )
        if not memory_user_seed:
            raise ProjectInstructionError("missing user memory seed: me.md")
        resolve_reconciliation(
            request_id="shared.memory.agent-marketplace",
            surface=f"{workspace}/memory/agent-marketplace.md",
            reason="unmanaged_content",
            source=memory_existing,
            companion=memory_root / "me.md",
            choices=choices,
            changes=changes,
            requests=requests,
            host=host,
            empty_companion_seed=memory_user_seed,
        )
    if memory_existing != memory_rendered:
        changes[memory_target] = memory_rendered

    if seed_user_files:
        for filename in ("me.md", "profile.md"):
            target_path = memory_root / filename
            if target_path.exists() or target_path in changes:
                continue
            seed_path = plugin_root / "templates" / "memory" / filename
            seed_text = read_regular(seed_path)
            if not seed_text:
                raise ProjectInstructionError(f"missing user memory seed: {seed_path}")
            changes[target_path] = seed_text

    current_surfaces = owned_surfaces(project_root, team, host, workspace)
    target_surfaces = dict(current_surfaces)
    target_surfaces[root_key] = sha256_text(target)
    if host == "codex":
        target_surfaces["AGENTS.override.md#reserved-absence"] = "absent"
    target_surfaces[memory_key] = sha256_text(memory_rendered)
    return {
        "changes": changes,
        "choice_requests": requests,
        "current_surfaces": current_surfaces,
        "target_surfaces": target_surfaces,
        "override_state": override_state,
    }


def plan_portable_project_files(
    project_root: Path,
    plugin_root: Path,
    workspace: str,
    *,
    choices: dict[str, str] | None = None,
    seed_user_files: bool = False,
) -> dict:
    """Plan the tracked contract for every supported host.

    A clone must be usable by either host even when setup is invoked from only
    one of them. Host-local projections remain outside this portable plan.
    """
    changes: dict[Path, str | None] = {}
    requests: dict[str, dict] = {}
    current: dict[str, str] = {}
    target: dict[str, str] = {}
    override_state = "absent"
    for host in ("claude", "codex"):
        result = plan_project_files(
            project_root, plugin_root, host, workspace,
            choices=choices, seed_user_files=seed_user_files,
        )
        for path, content in result["changes"].items():
            previous = changes.get(path)
            if path in changes and previous != content:
                raise ProjectInstructionError(
                    f"cross-host project content mismatch: {path}"
                )
            changes[path] = content
        for request in result["choice_requests"]:
            request_id = str(request.get("id", ""))
            previous = requests.get(request_id)
            if previous is not None and previous != request:
                raise ProjectInstructionError(
                    f"cross-host project choice mismatch: {request_id}"
                )
            requests[request_id] = request
        for source, destination in (
            (result["current_surfaces"], current),
            (result["target_surfaces"], target),
        ):
            for key, value in source.items():
                portable = key if key.startswith("shared:") else f"{host}:{key}"
                previous = destination.get(portable)
                if previous is not None and previous != value:
                    raise ProjectInstructionError(
                        f"cross-host project surface mismatch: {portable}"
                    )
                destination[portable] = value
        if host == "codex":
            override_state = result["override_state"]
    return {
        "changes": changes,
        "choice_requests": [requests[key] for key in sorted(requests)],
        "current_surfaces": current,
        "target_surfaces": target,
        "override_state": override_state,
    }


def owned_surfaces(
    project_root: Path, team: str, host: str, workspace: str,
) -> dict[str, str]:
    root_name = "AGENTS.md" if host == "codex" else "CLAUDE.md"
    root_path = project_root / root_name
    text = read_regular(root_path)
    result: dict[str, str] = {}
    if text:
        header = text.splitlines()[0]
        if header == generated_header(team, host):
            result[root_name] = sha256_text(text)
    if host == "codex":
        override = project_root / "AGENTS.override.md"
        if override.exists() or override.is_symlink():
            value = read_regular(override)
            result["AGENTS.override.md#reserved-absence"] = (
                "present:" + sha256_text(value)
            )
        else:
            result["AGENTS.override.md#reserved-absence"] = "absent"
    memory = project_root / workspace / "memory" / "agent-marketplace.md"
    value = read_regular(memory)
    if value and value.splitlines()[0] == generated_header(
        "software-engineering-team", "shared"
    ):
        result[f"shared:{workspace}/memory/agent-marketplace.md"] = sha256_text(value)
    return result


def owned_portable_surfaces(
    project_root: Path, team: str, workspace: str,
) -> dict[str, str]:
    result: dict[str, str] = {}
    for host in ("claude", "codex"):
        for key, value in owned_surfaces(
            project_root, team, host, workspace
        ).items():
            portable = key if key.startswith("shared:") else f"{host}:{key}"
            prior = result.get(portable)
            if prior is not None and prior != value:
                raise ProjectInstructionError(
                    f"cross-host project surface mismatch: {portable}"
                )
            result[portable] = value
    return result


def atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(dir=str(path.parent), prefix=f".{path.name}.")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise


def apply_changes(
    changes: dict[Path, str | None],
    writer: Callable[[Path, str], None] = atomic_write,
) -> list[Path]:
    snapshots = {
        path: path.read_bytes() if path.is_file() else None for path in changes
    }
    written: list[Path] = []
    try:
        for path, content in changes.items():
            if content is None:
                path.unlink(missing_ok=True)
            else:
                writer(path, content)
            written.append(path)
    except Exception:
        for path, previous in snapshots.items():
            if previous is None:
                path.unlink(missing_ok=True)
            else:
                path.parent.mkdir(parents=True, exist_ok=True)
                atomic_write(path, previous.decode("utf-8"))
        raise
    return written


def parse_choices(values: list[str] | None) -> dict[str, str]:
    result: dict[str, str] = {}
    for value in values or []:
        request_id, separator, selected = value.partition("=")
        if not separator or not request_id or selected not in CHOICE_OPTIONS:
            raise ProjectInstructionError(
                f"invalid --choice {value!r}; expected <id>=preserve|discard|abort"
            )
        if request_id in result and result[request_id] != selected:
            raise ProjectInstructionError(f"conflicting choices for {request_id}")
        result[request_id] = selected
    return result
